			if ac[i].idx > bc[i].idx {
				return -1
			}
			return 1
		}
		if c := strings.Compare(ac[i].tag, bc[i].tag); c != 0 {
			return c
		}
	}
	if len(ac) > len(bc) {
		return -1
	}
	if len(ac) < len(bc) {
		return 1
	}
	return 0
}

